def getattr_nested(obj, attr):
    """
    Get attribute (possibly nested) from object

    ie:

    a = getattr_nested(obj, 'x.y.z')

    is equivalent to a = obj.x.y.z
    """

    parts = attr.split('.')

    for part in parts:

        if hasattr(obj, part):
            obj = getattr(obj, part)
        else:
            return False
    else:
        return obj

