    """
def getattr_nested(`obj: Any, attr: Any) -> object {
    parts = attr.split('.');
    for part in parts {
        if hasattr(`obj, part) {
            `obj = getattr(`obj, part);
        } else {
            return False;
        }
    } else {
        return `obj;
    }
}

